preConditionHook:
// GUARD (2026-09-17): firstBar is the guard. On a date-change bar the prior
// day is complete, so prevClose (CloseD(1) in the twin) is always real there;
// the old test of the price against -1 was dead on real prices and a false
// negative on a back-adjusted series printing -1.00. Mentions of the -1
// SENTINEL below describe what CloseD returns, not how this rule guards it.
// The session's first bar opens at least gapAtrMultiple ATRs ABOVE the prior
// session's close (long) or below it (short) -- a SIGNED gap-size test, the
// opening gap read as a spike in its own direction. One source treats it as
// the spike of a spike-and-channel day, the other as a directional tilt;
// behaviourally that is one test. 0.5 and 1.0 ATR were both stated, 1.0 kept.
//
// Kept apart from SessionGapAtrMagnitude, the same measurement UNSIGNED.
// Neither is the other with a placement toggle: a placement carries one side
// and the panes AND entry rules rather than OR them, so the two-sided reading
// cannot be built out of this one.
//
// SESSION MODEL, per the standing decision: the first bar of a session is the
// wall-clock close-date change, day_of(ctx.Time(0)) > day_of(ctx.Time(1)) --
// the twin's date > date[1].
//
// prevClose IS CloseD(1), which the twin calls and the engine does not
// expose. MEASURED (the closed register row): the day is the wall-clock
// CALENDAR date, the same boundary as date <> date[1], and the function
// returns a -1 SENTINEL while fewer than that many complete days exist. The
// mirror is exact from its first observed date change on, because a day's
// close is simply the close of its LAST bar and close[1] on the date-change
// bar is exactly that -- no running accumulator and no sawStart guard are
// needed, unlike HighD/LowD. Before that first observed change TradeStation
// can already answer from chart data the engine's window never showed it, so
// the mirror holds the -1 sentinel there and is silent: the engine's window
// is part of the specification and the mirror errs toward no signal.
//
// WFSafe_AvgTrueRange is MultiWalk's ROLLING accumulator, not a fresh N-term
// mean: seeded with a full sum on the study's first calculated bar and
// thereafter S += TrueRange - TrueRange[Length], re-seeding on a length change.
// Ported from AtrProfitTarget, including the TWO separate statements --
// EasyLanguage evaluates Summation[1] + Price - Price[Length] left to right
// and folding it to S += in - out rounds onto the other side of a threshold.
// The accumulator stays in the hook, which the generator emits
// unconditionally: EL does not short-circuit, so a stateful call inside a
// condition would advance every bar in EL and only on some bars here.
//
// Not LargeGapVsAverageRange, whose gap is the whole-range non-overlap with
// the PREVIOUS BAR at any point of the chart. Intraday bars only.
if (atrLenState != (int)atrLength) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLength; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLenState = (int)atrLength;
} else {
    const int out = (int)atrLength;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrValue = atrSum / (int)atrLength;
if (day_of(ctx.Time(0)) > day_of(ctx.Time(1))) {
    prevClose = close[1];
    firstBar = true;
} else {
    firstBar = false;
}
gapUp = firstBar
    && el_ge(open[0] - prevClose, gapAtrMultiple * atrValue);
gapDn = firstBar
    && el_ge(prevClose - open[0], gapAtrMultiple * atrValue);
